local function getOtherPlayerNames()
	local names = {}
	for _, player in ipairs(Players:GetPlayers()) do
		-- Жесткая проверка: если это мы, пропускаем на 100%
		if player.Name == game.Players.LocalPlayer.Name then 
			continue 
		end
		table.insert(names, player.Name)
	end

	-- Если никого нет, возвращаем пустую таблицу с одной строкой-заглушкой
	if #names == 0 then
		return {"Нет других игроков"}
	end
	return names
end

