-- Получаем персонажа в зависимости от того, где лежит LocalScript
local character = game.Players.LocalPlayer.Character
local humanoid = character:WaitForChild("Humanoid")
local animator = humanoid:WaitForChild("Animator")

local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local CustomPlayer = {}
CustomPlayer.__index = CustomPlayer

-- Перенаправитель имен костей для корректного поиска моторов в R15
local R6ToR15Names = {
	["Torso"]       = "LowerTorso",
	["Head"]        = "Head",
	["Left Arm"]    = "LeftUpperArm",
	["Right Arm"]   = "RightUpperArm",
	["Left Leg"]    = "LeftUpperLeg",
	["Right Leg"]   = "RightUpperLeg"
}

-- Конструктор: принимает персонажа чужого игрока и таблицу данных animData
function CustomPlayer.new(targetCharacter, data)
	local self = setmetatable({}, CustomPlayer)
	self.Character = targetCharacter
	self.Data = data
	self.Connection = nil
	self.IsPlaying = false
	self.ActiveMotors = {}
	self.DefaultC0s = {}

	-- Ищем гуманоид и аниматор у ЦЕЛЕВОГО персонажа
	self.Humanoid = targetCharacter:WaitForChild("Humanoid", 5)
	self.Animator = self.Humanoid and self.Humanoid:WaitForChild("Animator", 5)

	-- Определяем тип рига один раз при инициализации
	self.IsR15 = self.Humanoid and self.Humanoid.RigType == Enum.HumanoidRigType.R15

	-- Собираем все Motor6D персонажа
	local characterMotors = {}
	for _, desc in ipairs(targetCharacter:GetDescendants()) do
		if desc:IsA("Motor6D") and desc.Part1 then
			characterMotors[desc.Part1.Name] = desc
		end
	end

	-- Кэшируем Motor6D и оригинальные C0 (с поддержкой имен R15, если риг R15)
	for animPartName, frames in pairs(self.Data.Motors) do
		local realPartName = animPartName

		if self.IsR15 and R6ToR15Names[animPartName] then
			realPartName = R6ToR15Names[animPartName]
		end

		local motor = characterMotors[realPartName]
		if motor then
			-- Кэшируем по оригинальному имени из animData, чтобы evaluateC0 работал стабильно
			self.ActiveMotors[animPartName] = motor
			self.DefaultC0s[animPartName] = motor.C0
		end
	end
	return self
end

-- Внутренняя функция принудительного изменения веса анимаций целевого игрока
local function setTargetAnimsWeight(self, weight)
	if not self.Animator then return end
	for _, track in ipairs(self.Animator:GetPlayingAnimationTracks()) do
		track:AdjustWeight(weight, 0.05) -- Быстро глушим/возвращаем вес
	end
end

-- Твоя стабильная функция математического сглаживания кадров (без изменений)
local function evaluateC0(frames, t, loopLength, defaultC0)
	if not frames or #frames == 0 then return nil end
	if #frames == 1 then return defaultC0 * frames.CFrame end

	local k1, k2 = frames, frames[#frames]
	for i = 1, #frames - 1 do
		if t >= frames[i].Time and t <= frames[i+1].Time then
			k1 = frames[i] k2 = frames[i+1] break
		end
	end
	if t > frames[#frames].Time then k1 = frames[#frames] k2 = frames end

	local duration = k2.Time - k1.Time
	if duration <= 0 then duration = (loopLength - k1.Time) + k2.Time end
	local elapsed = t - k1.Time
	if elapsed < 0 then elapsed = elapsed + loopLength end

	local alpha = duration > 0 and (elapsed / duration) or 0
	return (defaultC0 * k1.CFrame):Lerp(defaultC0 * k2.CFrame, math.clamp(alpha, 0, 1))
end

-- МЕТОД ЗАПУСКА
function CustomPlayer:StartAnimation()
	if self.IsPlaying or not self.Character then return end
	self.IsPlaying = true

	setTargetAnimsWeight(self, 0)

	local startTime = os.clock()

	self.Connection = RunService.RenderStepped:Connect(function()
		if not self.Character or not self.Character.Parent then
			self:StopAnimation()
			return
		end

		local elapsed = os.clock() - startTime
		local currentTime = elapsed % self.Data.Length

		if self.Animator then
			for _, track in ipairs(self.Animator:GetPlayingAnimationTracks()) do
				track:AdjustWeight(0, 0)
			end
		end

		for animPartName, motor in pairs(self.ActiveMotors) do
			local nextC0 = evaluateC0(self.Data.Motors[animPartName], currentTime, self.Data.Length, self.DefaultC0s[animPartName])

			if nextC0 then
				if self.IsR15 then
					-- ТОЛЬКО ДЛЯ R15: Жесткое смещение позиции торса
					if animPartName == "Torso" then
						-- Вытаскиваем чистый поворот из получившегося кадра
						local pureRotation = nextC0 - nextC0.Position

						-- Берем базовую позицию C0, прибавляем оффсет (Y = +5, Z = -3)
						local basePos = self.DefaultC0s[animPartName].Position
						local targetPosition = Vector3.new(basePos.X, basePos.Y + 5, basePos.Z - 3)

						-- Собираем финальный CFrame: новая жесткая позиция + оригинальный поворот кадра
						motor.C0 = CFrame.new(targetPosition) * pureRotation
					else
						motor.C0 = nextC0
					end
				else
					-- ДЛЯ R6: Играет чистый стабильный код без изменений
					motor.C0 = nextC0
				end
			end
		end
	end)
end

-- МЕТОД ОСТАНОВКИ
function CustomPlayer:StopAnimation()
	if not self.IsPlaying then return end
	self.IsPlaying = false

	if self.Connection then 
		self.Connection:Disconnect() 
		self.Connection = nil 
	end

	-- Возвращаем все Motor6D чужого персонажа строго в дефолт
	for animPartName, motor in pairs(self.ActiveMotors) do
		if motor and motor.Parent then
			motor.C0 = self.DefaultC0s[animPartName]
		end
	end

	-- Возвращаем чужому игроку его стандартные анимации
	setTargetAnimsWeight(self, 1)
end

local btrack
local gtrack

function Bang(state)
	if state then
		if game.Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid").RigType == Enum.HumanoidRigType.R6 then
			if bangtarget == nil then print("Empty") return end
			game.Players:FindFirstChild(bangtarget).Character.HumanoidRootPart.Anchored = true
			game.Players.LocalPlayer.Character.HumanoidRootPart.Anchored = true
			game.Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid").AutoRotate = false
			game.Players:FindFirstChild(bangtarget).Character.HumanoidRootPart.CFrame = game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame
			if game.Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid").RigType == Enum.HumanoidRigType.R6 then
				btrack = CustomPlayer.new(game.Players.LocalPlayer.Character, BanimData)
			else
				btrack = CustomPlayer.new(game.Players.LocalPlayer.Character, R15BanimData)
			end
			if game.Players:FindFirstChild(bangtarget).Character:FindFirstChildOfClass("Humanoid").RigType == Enum.HumanoidRigType.R6 then
				gtrack = CustomPlayer.new(game.Players:FindFirstChild(bangtarget).Character, GanimData)
			else
				gtrack = CustomPlayer.new(game.Players:FindFirstChild(bangtarget).Character, R15GanimData)
			end
			
			btrack:StartAnimation()
			gtrack:StartAnimation()
		end
	else
		game.Players:FindFirstChild(bangtarget).Character.HumanoidRootPart.Anchored = false
		game.Players.LocalPlayer.Character.HumanoidRootPart.Anchored = false
		game.Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid").AutoRotate = true
		btrack:StopAnimation()
		gtrack:StopAnimation()
		btrack = nil
		gtrack = nil
	end
end

