			long2.Material = Enum.Material.SmoothPlastic
			long2.Size = Vector3.new(0.8999999761581421, 2, 0.5)
			long2.CanTouch = false
			long2.AudioCanCollide = false
			long2.Shape = Enum.PartType.Cylinder
			long2.Parent = MainPartB

			local WeldConstraint3 = Instance.new("WeldConstraint")
			WeldConstraint3.Parent = long2

			local head = Instance.new("Part")
			head.Name = "head"
			head.CFrame = CFrame.new(78, 3.1545257568359375, 67.5, 1, 0, 0, 0, 0.9999998807907104, 4.470348358154297e-08, 0, 1.4901161193847656e-08, 0.9999998807907104)
			head.AssemblyAngularVelocity = Vector3.new(-7.377592425861224e-10, -4.929273184767944e-19, -4.7464512320516405e-09)
			head.BottomSurface = Enum.SurfaceType.Smooth
			head.CanCollide = false
			head.AssemblyLinearVelocity = Vector3.new(-7.542144686567553e-11, 0.000006595186732738512, 1.1723011450470722e-11)
			head.Velocity = Vector3.new(-4.0884216012671004e-09, 0.000006593342277483316, 6.354790582641101e-10)
			head.TopSurface = Enum.SurfaceType.Smooth
			head.CanQuery = false
			head.Color = Color3.fromRGB(165, 96, 96)
			head.Massless = true
			head.RotVelocity = Vector3.new(-7.377592425861224e-10, -4.929273184767944e-19, -4.7464512320516405e-09)
			head.Material = Enum.Material.SmoothPlastic
			head.Size = Vector3.new(0.5999999642372131, 0.5999999642372131, 0.5999999642372131)
			head.CanTouch = false
			head.AudioCanCollide = false
			head.Shape = Enum.PartType.Ball
			head.Parent = MainPartB

			local WeldConstraint4 = Instance.new("WeldConstraint")
			WeldConstraint4.Parent = head

			local hole1 = Instance.new("Part")
			hole1.Name = "hole1"
			hole1.CFrame = CFrame.new(78, 3.176928997039795, 67.42050170898438, 1, 0, 0, 0, 0.9999999403953552, 1.490117540470237e-08, 0, 1.4901146982992941e-08, 0.9999999403953552)
			hole1.AssemblyAngularVelocity = Vector3.new(-7.377592425861224e-10, -4.929273184767944e-19, -4.7464512320516405e-09)
			hole1.BottomSurface = Enum.SurfaceType.Smooth
			hole1.CanCollide = false
			hole1.AssemblyLinearVelocity = Vector3.new(-7.542144686567553e-11, 0.000006595186732738512, 1.1723011450470722e-11)
			hole1.Velocity = Vector3.new(-3.9820857722361325e-09, 0.000006593283615075052, 6.189508905407592e-10)
			hole1.TopSurface = Enum.SurfaceType.Smooth
			hole1.CanQuery = false
			hole1.Color = Color3.fromRGB(84, 47, 47)
			hole1.Massless = true
			hole1.RotVelocity = Vector3.new(-7.377592425861224e-10, -4.929273184767944e-19, -4.7464512320516405e-09)
			hole1.Material = Enum.Material.SmoothPlastic
			hole1.Size = Vector3.new(0.030561327934265137, 1.3790661096572876, 0.4348803460597992)
			hole1.CanTouch = false
			hole1.AudioCanCollide = false
			hole1.Shape = Enum.PartType.Cylinder
			hole1.Parent = MainPartB

			local WeldConstraint5 = Instance.new("WeldConstraint")
			WeldConstraint5.Parent = hole1

			local WeldConstraint6 = Instance.new("WeldConstraint")
			WeldConstraint6.Parent = MainPartB

			WeldConstraint.Part1 = long
			WeldConstraint.Part0 = egg

			WeldConstraint1.Part1 = egg2
			WeldConstraint1.Part0 = long

			WeldConstraint2.Part1 = head
			WeldConstraint2.Part0 = egg2

			WeldConstraint3.Part1 = hole1
			WeldConstraint3.Part0 = long2

			WeldConstraint4.Part1 = long2
			WeldConstraint4.Part0 = head

			WeldConstraint5.Part1 = MainPartB
			WeldConstraint5.Part0 = hole1

			WeldConstraint6.Part1 = egg
			WeldConstraint6.Part0 = MainPartB

			MainPartB.Parent = game.Players.LocalPlayer.Character
			local weld = Instance.new("WeldConstraint", MainPartB)
			MainPartB:PivotTo(game.Players.LocalPlayer.Character.Torso:GetPivot())
			weld.Part0 = MainPartB
			weld.Part1 = game.Players.LocalPlayer.Character.Torso
			MainPartB.Anchored = false
			long.Color = game.Players.LocalPlayer.Character.Head.Color
			long2.Color = game.Players.LocalPlayer.Character.Head.Color
			egg.Color = game.Players.LocalPlayer.Character.Head.Color
			egg2.Color = game.Players.LocalPlayer.Character.Head.Color
			if game.Players.LocalPlayer.Character:FindFirstChildOfClass("Shirt") then
				game.Players.LocalPlayer.Character:FindFirstChildOfClass("Shirt").Parent = MainPartB
			end
			if game.Players.LocalPlayer.Character:FindFirstChildOfClass("ShirtGraphic") then
				game.Players.LocalPlayer.Character:FindFirstChildOfClass("ShirtGraphic").Parent = MainPartB
			end
			if game.Players.LocalPlayer.Character:FindFirstChildOfClass("Pants") then
				game.Players.LocalPlayer.Character:FindFirstChildOfClass("Pants").Parent = MainPartB
			end
			for _,v in pairs(game.Players.LocalPlayer.Character:GetChildren()) do
				if v:IsA("BasePart") and v.Name ~= "Head" and v.Name ~= MainPartB.Name then
					v.Color = game.Players.LocalPlayer.Character.Head.Color
				end
			end
		end
	else
		local character = game.Players.LocalPlayer.Character
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		local bodyColors = character:FindFirstChildOfClass("BodyColors")

		if not humanoid or not bodyColors then
			warn("Не удалось найти Humanoid или BodyColors в персонаже!")
			return
		end

		-- Проверяем тип рига персонажа
		if humanoid.RigType == Enum.HumanoidRigType.R6 then
			---------------------------------------------------------------------
			-- ЛОГИКА ДЛЯ R6 (Всего 6 основных партов)
			---------------------------------------------------------------------
			if character:FindFirstChild("Head") then character.Head.Color = bodyColors.HeadColor3 end
			if character:FindFirstChild("Torso") then character.Torso.Color = bodyColors.TorsoColor3 end

			if character:FindFirstChild("Left Arm") then character["Left Arm"].Color = bodyColors.LeftArmColor3 end
			if character:FindFirstChild("Right Arm") then character["Right Arm"].Color = bodyColors.RightArmColor3 end

			if character:FindFirstChild("Left Leg") then character["Left Leg"].Color = bodyColors.LeftLegColor3 end
			if character:FindFirstChild("Right Leg") then character["Right Leg"].Color = bodyColors.RightLegColor3 end

		elseif humanoid.RigType == Enum.HumanoidRigType.R15 then
			---------------------------------------------------------------------
			-- ЛОГИКА ДЛЯ R15 (15 партов, разделенных по суставам)
			---------------------------------------------------------------------
			-- Голова
			if character:FindFirstChild("Head") then character.Head.Color = bodyColors.HeadColor3 end

			-- Торс (Верх и низ)
			if character:FindFirstChild("UpperTorso") then character.UpperTorso.Color = bodyColors.TorsoColor3 end
			if character:FindFirstChild("LowerTorso") then character.LowerTorso.Color = bodyColors.TorsoColor3 end

			-- Левая рука (Плечо, предплечье, кисть)
			if character:FindFirstChild("LeftUpperArm") then character.LeftUpperArm.Color = bodyColors.LeftArmColor3 end
			if character:FindFirstChild("LeftLowerArm") then character.LeftLowerArm.Color = bodyColors.LeftArmColor3 end
			if character:FindFirstChild("LeftHand") then character.LeftHand.Color = bodyColors.LeftArmColor3 end

			-- Правая рука (Плечо, предплечье, кисть)
			if character:FindFirstChild("RightUpperArm") then character.RightUpperArm.Color = bodyColors.RightArmColor3 end
			if character:FindFirstChild("RightLowerArm") then character.RightLowerArm.Color = bodyColors.RightArmColor3 end
			if character:FindFirstChild("RightHand") then character.RightHand.Color = bodyColors.RightArmColor3 end

			-- Левая нога (Бедро, голень, ступня)
			if character:FindFirstChild("LeftUpperLeg") then character.LeftUpperLeg.Color = bodyColors.LeftLegColor3 end
			if character:FindFirstChild("LeftLowerLeg") then character.LeftLowerLeg.Color = bodyColors.LeftLegColor3 end
			if character:FindFirstChild("LeftFoot") then character.LeftFoot.Color = bodyColors.LeftLegColor3 end

			-- Правая нога (Бедро, голень, ступня)
			if character:FindFirstChild("RightUpperLeg") then character.RightUpperLeg.Color = bodyColors.RightLegColor3 end
			if character:FindFirstChild("RightLowerLeg") then character.RightLowerLeg.Color = bodyColors.RightLegColor3 end
			if character:FindFirstChild("RightFoot") then character.RightFoot.Color = bodyColors.RightLegColor3 end
		end
		if MainPartB:FindFirstChildOfClass("Shirt") then
			MainPartB:FindFirstChildOfClass("Shirt").Parent = character
		end
		if MainPartB:FindFirstChildOfClass("ShirtGraphic") then
			MainPartB:FindFirstChildOfClass("ShirtGraphic").Parent = character
		end
		if MainPartB:FindFirstChildOfClass("Pants") then
			MainPartB:FindFirstChildOfClass("Pants").Parent = character
		end
		MainPartB:Destroy()
		MainPartB = nil
	end
end

game.Players.LocalPlayer.CharacterAdded:Connect(function()
	MainPartB = nil
	while not game.Players.LocalPlayer:HasAppearanceLoaded() do
		task.wait(0.1)
	end
	task.wait(0.1)
	ToggleBMorph(bmorph)
end)
